// The FP8 tile rules against Pearl's own answers, generated by
// vectors/generate.py from the fp8-scheme miner code.
import { describe, expect, it } from 'vitest';
import vectors from '../vectors/tiles.json' with { type: 'json' };
import { denseTile, type Arch } from '../src/rules.js';

const code = { '4x64': 'a', '16x32': 'b', '4x128': 'c' } as const;

describe('dense tile choice', () => {
  for (const arch of ['SM90', 'SM100', 'SM120'] as Arch[]) {
    it(`matches Pearl's select_tile and kernel check on every grid shape for ${arch}`, () => {
      const grid = vectors.grid[arch];
      const wrong: string[] = [];
      vectors.n.forEach((n, i) =>
        vectors.k.forEach((k, j) => {
          const tile = denseTile(n, k, arch);
          const got = tile ? code[tile] : '-';
          if (got !== grid[i]![j]) wrong.push(`${n}x${k}: ${got} vs ${grid[i]![j]}`);
        }),
      );
      expect(wrong.slice(0, 10)).toEqual([]);
    });
  }

  it('leaves k-wide layers past 42,496 to the B200 tall tile only', () => {
    expect(denseTile(4096, 43008, 'SM100')).toBe('16x32');
    expect(denseTile(4096, 43008, 'SM90')).toBeNull();
    expect(denseTile(4096, 43008, 'SM120')).toBeNull();
  });
});
